        return ([], [])

    elements = []
    counts = []

    current = lst[0]
    count = 1

    for i in range(1, len(lst)):
        if lst[i] == current:
            count += 1
        else:
            elements.append(current)
            counts.append(count)
            current = lst[i]
            count = 1

